tippy('.settsunokuni', { content: '<h3><ruby>摂津国<rt>せっつのくに</rt></ruby></h3>【名詞】摂津国は、現在の大阪府北中部の大半、兵庫県南東部を占める令制国です。', allowHTML: true });

