tippy('.rokyo', { content: '<h3><ruby>老境<rt>ろうきょう</rt></ruby></h3>【名詞】老齢になった境地。平安時代では、現代と比べると、平均寿命が短く、40歳は初老の年齢と考えられていました。現代では考えにくいですが、当時は、満年齢39歳で「四十の賀」という四十歳になったことを初老として、長寿を祈る賀の祝いが行われていました。', allowHTML: true });
