tippy('.uji', { content: '<div style="display:flex; flex-direction:column; gap:10px;"><div style="display:flex; flex-direction:column; "><h3 style="margin-bottom:5px;"><ruby>宇治<rt>うじ</rt></ruby></h3><p>【地名】現在の京都府南部。平安時代から貴族の別荘地で、源氏物語の舞台にもなりました。</p></div></div>', allowHTML: true });
